/*
 * manager.c - ExStarModManager.exe
 *
 * Installer / enabler / remover for EXStar Hub mods. Single file: the
 * bootstrap proxy, the host and every module DLL are embedded as RCDATA
 * resources (see build\manager.rc, generated by build.ps1), so the whole
 * release is ONE executable.
 *
 * GUI : checkboxes per module + three actions
 *       (install selected / remove selected / restore stock).
 * CLI : ExStarModManager.exe --install  (all bundled modules; use
 *       --modules marker_inframe[,id2|all] to restrict the set)
 *       ExStarModManager.exe --remove  --modules id1,id2
 *       ExStarModManager.exe --restore
 *       ExStarModManager.exe --list
 *       optional: --app "D:\path\to\EXStar Hub"
 *
 * The manager is marked requireAdministrator (writes to Program Files).
 * It never modifies vendor files: everything it places is recorded in
 * `<app dir>\exstar_mods.state`, and "restore stock" deletes exactly the
 * recorded files. A foreign (vendor) winmm.dll in the app directory is
 * detected by its version resource and aborts the install.
 */

