static HINSTANCE g_hInst;

static void w2a(const wchar_t *w, char *a, int cap)
{
    WideCharToMultiByte(CP_UTF8, 0, w, -1, a, cap, NULL, NULL);
}
static void a2w(const char *a, wchar_t *w, int cap)
{
    MultiByteToWideChar(CP_UTF8, 0, a, -1, w, cap);
}

static BOOL pathExistsA(const char *p)
{
    DWORD a = GetFileAttributesA(p);
    return a != INVALID_FILE_ATTRIBUTES;
}

static void ensureDirA(const char *dir)
{
    CreateDirectoryA(dir, NULL);
}

/* OriginalFilename from the version resource ('' when absent). */
static BOOL origNameW(const wchar_t *path, wchar_t *out, int cap)
{
    DWORD sz = GetFileVersionInfoSizeW(path, NULL);
    BOOL ok = FALSE;
    out[0] = 0;
    if (sz) {
        void *data = HeapAlloc(GetProcessHeap(), 0, sz);
        if (data && GetFileVersionInfoW(path, 0, sz, data)) {
            struct { WORD lang, codepage; } *tr = NULL;
            UINT n = 0;
            if (VerQueryValueW(data, L"\\VarFileInfo\\Translation", (void **)&tr, &n) && n) {
                wchar_t q[128];
                void *val = NULL;
                swprintf(q, 128, L"\\StringFileInfo\\%04x%04x\\OriginalFilename",
                         tr->lang, tr->codepage);
                if (VerQueryValueW(data, q, &val, &n) && n) {
                    wcsncpy(out, (const wchar_t *)val, cap - 1);
                    out[cap - 1] = 0;
                    ok = TRUE;
                }
            }
        }
        if (data)
            HeapFree(GetProcessHeap(), 0, data);
    }
    return ok;
}

static BOOL fileOriginalEq(const char *pathA, const wchar_t *want)
{
    wchar_t p[MAX_PATH], name[256];
    a2w(pathA, p, MAX_PATH);
    return origNameW(p, name, 256) && _wcsicmp(name, want) == 0;
}

static void appVersion(const char *appDirA, wchar_t *out, int cap)
{
    wchar_t p[MAX_PATH], dirW[MAX_PATH];
    wchar_t name[256];
    void *data = NULL;
    VS_FIXEDFILEINFO *ffi = NULL;
    UINT n = 0;
    DWORD sz;

    out[0] = 0;
    a2w(appDirA, dirW, MAX_PATH);
    swprintf(p, MAX_PATH, L"%ls\\%ls", dirW, APP_EXE_NAME);
    sz = GetFileVersionInfoSizeW(p, NULL);
    if (!sz)
        return;
    data = HeapAlloc(GetProcessHeap(), 0, sz);
    if (data && GetFileVersionInfoW(p, 0, sz, data)
        && VerQueryValueW(data, L"\\", (void **)&ffi, &n)
        && n >= sizeof *ffi) {
        swprintf(out, cap, L"%d.%d.%d.%d",
                 HIWORD(ffi->dwFileVersionMS), LOWORD(ffi->dwFileVersionMS),
                 HIWORD(ffi->dwFileVersionLS), LOWORD(ffi->dwFileVersionLS));
    }
    (void) name;
    if (data)
        HeapFree(GetProcessHeap(), 0, data);
}

/* Vendor product number (e.g. "2.1.0-10"): the uninstall key's
 * DisplayVersion, DisplayName's trailing number as a fallback. Scans
 * HKLM (64- and 32-bit views) and HKCU, matching by DisplayName so a
 * renamed key still resolves. Empty out when nothing matches. */
static void appProductVersion(wchar_t *out, int cap)
{
    static const HKEY roots[3]  = { HKEY_LOCAL_MACHINE, HKEY_LOCAL_MACHINE,
                                    HKEY_CURRENT_USER };
    static const DWORD flags[3] = { KEY_WOW64_64KEY, KEY_WOW64_32KEY, 0 };
    wchar_t sub[256], name[128], ver[64], *sp;
    DWORD i, idx, len;
    HKEY hUninst, hSub;

    out[0] = 0;
    for (i = 0; i < 3 && !out[0]; i++) {
        if (RegOpenKeyExW(roots[i],
                L"SOFTWARE\\Microsoft\\Windows\\CurrentVersion\\Uninstall",
                0, KEY_READ | flags[i], &hUninst) != ERROR_SUCCESS)
            continue;
        for (idx = 0; !out[0]; idx++) {
            len = ARRAYSIZE(sub);
            if (RegEnumKeyExW(hUninst, idx, sub, &len,
                              NULL, NULL, NULL, NULL) != ERROR_SUCCESS)
                break;
            if (RegOpenKeyExW(hUninst, sub, 0, KEY_READ, &hSub) != ERROR_SUCCESS)
                continue;
            len = sizeof name;
            if (RegQueryValueExW(hSub, L"DisplayName", NULL, NULL,
                                 (BYTE *) name, &len) == ERROR_SUCCESS
                && _wcsnicmp(name, L"EXStar", 6) == 0) {
                len = sizeof ver;
                if (RegQueryValueExW(hSub, L"DisplayVersion", NULL, NULL,
                                     (BYTE *) ver, &len) != ERROR_SUCCESS
                    || !ver[0]) {
                    /* "EXStar Hub 2.1.0-10" -> last blank-separated word */
                    ver[0] = 0;
                    sp = name + lstrlenW(name);
                    while (sp > name && sp[-1] != L' ')
                        sp--;
                    if (*sp >= L'0' && *sp <= L'9') {
                        wcsncpy(ver, sp, ARRAYSIZE(ver) - 1);
                        ver[ARRAYSIZE(ver) - 1] = 0;
                    }
                }
                if (ver[0]) {
                    wcsncpy(out, ver, (size_t) cap - 1);
                    out[cap - 1] = 0;
                }
            }
            RegCloseKey(hSub);
        }
        RegCloseKey(hUninst);
    }
}

/* ---- process presence / kill ---- */

static BOOL appRunning(void)
{
    HANDLE snap = CreateToolhelp32Snapshot(TH32CS_SNAPPROCESS, 0);
    PROCESSENTRY32W pe;
    BOOL found = FALSE;

    pe.dwSize = sizeof pe;
    if (Process32FirstW(snap, &pe)) {
        do {
            if (_wcsicmp(pe.szExeFile, APP_EXE_NAME) == 0) {
                found = TRUE;
                break;
            }
        } while (Process32NextW(snap, &pe));
    }
    CloseHandle(snap);
    return found;
}

static void killApp(void)
{
    int i;
    system("taskkill /f /im \"" APP_EXE_A "\" >nul 2>&1");
    for (i = 0; i < 60 && appRunning(); i++)
        Sleep(500);
}

/* ------------------------------------------------------------------ */
/* embedded resources -> files                                         */
/* ------------------------------------------------------------------ */

static BOOL resourceWrite(LPCWSTR name, const char *dstPath)
{
    /* RT_RCDATA == 10; MAKEINTRESOURCEW: the project compiles without a
     * UNICODE define, so RT_RCDATA would resolve to the ANSI variant */
    HRSRC res = FindResourceW(g_hInst, name, MAKEINTRESOURCEW(10));
    HGLOBAL data;
    const void *p;
    DWORD size;
    HANDLE f;
    BOOL ok = FALSE;
    DWORD written;

    if (!res)
        return FALSE;
    data = LoadResource(g_hInst, res);
    p = LockResource(data);
    size = SizeofResource(g_hInst, res);
    if (!p || !size)
        return FALSE;
    f = CreateFileA(dstPath, GENERIC_WRITE, 0, NULL, CREATE_ALWAYS,
                    FILE_ATTRIBUTE_NORMAL, NULL);
    if (f != INVALID_HANDLE_VALUE) {
        ok = WriteFile(f, p, size, &written, NULL) && written == size;
        CloseHandle(f);
    }
    return ok;
}

/* A refused write is nearly always a permission problem, and a bare
 * error code sends the user hunting for the wrong file. */
static void report(const wchar_t *fmt, ...);

static void reportWriteErr(const char *what, DWORD err)
{
    if (err == ERROR_ACCESS_DENIED || err == ERROR_PRIVILEGE_NOT_HELD)
        report(L"%hs: access denied (err=%lu). Close EXStar Hub and, when "
               L"the folder is protected, start the manager as "
               L"administrator.", what, err);
    else
        report(L"%hs: write failed (err=%lu).", what, err);
}

/* ------------------------------------------------------------------ */
/* simple INI document (sections + key=value, comments ';')            */
/* ------------------------------------------------------------------ */

#define INI_SECS   24
#define INI_KEYS   16

typedef struct { char key[64], val[128]; } KV;
typedef struct { char name[64]; KV kv[INI_KEYS]; int n; } Sec;
typedef struct { Sec sec[INI_SECS]; int n; } IniDoc;

static Sec *iniSec(IniDoc *d, const char *name)
{
    int i;
    for (i = 0; i < d->n; i++)
        if (_stricmp(d->sec[i].name, name) == 0)
            return &d->sec[i];
    if (d->n >= INI_SECS)
        return NULL;
    strcpy_s(d->sec[d->n].name, 64, name);
    d->sec[d->n].n = 0;
    return &d->sec[d->n++];
}

static void iniRemoveSec(IniDoc *d, const char *name)
{
    int i, j;
    for (i = 0; i < d->n; i++) {
        if (_stricmp(d->sec[i].name, name) == 0) {
            for (j = i; j + 1 < d->n; j++)
                d->sec[j] = d->sec[j + 1];
            d->n--;
            return;
        }
    }
}

static void iniSet(Sec *s, const char *k, const char *v)
{
    int i;
    for (i = 0; i < s->n; i++)
        if (_stricmp(s->kv[i].key, k) == 0) {
            strcpy_s(s->kv[i].val, 128, v);
            return;
        }
    if (s->n < INI_KEYS) {
        strcpy_s(s->kv[s->n].key, 64, k);
        strcpy_s(s->kv[s->n].val, 128, v);
        s->n++;
    }
}

static BOOL iniLoad(IniDoc *d, const char *path)
{
    FILE *f = fopen(path, "rb");
    char line[512];
    Sec *cur = NULL;

    memset(d, 0, sizeof *d);
    if (!f)
        return FALSE;
    while (fgets(line, sizeof line, f)) {
        char *hash = strchr(line, '#');
        char *semi = strchr(line, ';');
        char *s = line;
        char *close, *sep;

        if (hash && (!semi || hash < semi))
            *hash = 0;
        if (semi)
            *semi = 0;
        while (*s == ' ' || *s == '\t')
            s++;
        if (!*s || *s == '\r' || *s == '\n')
            continue;
        if (*s == '[') {
            close = strchr(s, ']');
            if (close) {
                *close = 0;
                cur = iniSec(d, s + 1);
            }
            continue;
        }
        sep = strchr(s, '=');
        if (!sep || !cur)
            continue;
        *sep = 0;
        {
            char *v = sep + 1;
            char *end;
            while (*v == ' ' || *v == '\t')
                v++;
            end = v + strlen(v);
            while (end > v && (end[-1] == ' ' || end[-1] == '\t'
                               || end[-1] == '\r' || end[-1] == '\n'))
                *--end = 0;
            {
                char *k = s, *ke = sep - 1;
                while (ke > k && (ke[-1] == ' ' || ke[-1] == '\t'))
                    ke--;
                *ke = 0;
                iniSet(cur, k, v);
            }
        }
    }
    fclose(f);
    return TRUE;
}

static BOOL iniSave(const IniDoc *d, const char *path)
{
    FILE *f = fopen(path, "wb");
    int i, j;
    if (!f)
        return FALSE;
    fprintf(f, "; ExStar Hub Mods - module switches (applied at app start)\n");
    for (i = 0; i < d->n; i++) {
        fprintf(f, "\n[%s]\n", d->sec[i].name);
        for (j = 0; j < d->sec[i].n; j++)
            fprintf(f, "%s = %s\n", d->sec[i].kv[j].key, d->sec[i].kv[j].val);
    }
    fclose(f);
    return TRUE;
}

/* ------------------------------------------------------------------ */
/* state manifest: files placed by this manager (relative paths)       */
/* ------------------------------------------------------------------ */

typedef struct { char line[MAX_STATE][MAX_PATH]; int n; } State;

static BOOL stateLoad(State *st, const char *appDir)
{
    char path[MAX_PATH];
    FILE *f;
    st->n = 0;
    snprintf(path, sizeof path, "%s\\exstar_mods.state", appDir);
    f = fopen(path, "rb");
    if (!f)
        return FALSE;
    while (st->n < MAX_STATE && fgets(st->line[st->n], MAX_PATH, f)) {
        char *e = st->line[st->n] + strlen(st->line[st->n]);
        while (e > st->line[st->n] && (e[-1] == '\r' || e[-1] == '\n'))
            *--e = 0;
        if (st->line[st->n][0] != ';')
            st->n++;
    }
    fclose(f);
    return TRUE;
}

static void stateAdd(State *st, const char *rel)
{
    int i;
    for (i = 0; i < st->n; i++)
        if (_stricmp(st->line[i], rel) == 0)
            return;
    if (st->n < MAX_STATE)
        strcpy_s(st->line[st->n++], MAX_PATH, rel);
}

static void stateDrop(State *st, const char *prefix)
{
    int i, w = 0;
    for (i = 0; i < st->n; i++) {
        if (_strnicmp(st->line[i], prefix, strlen(prefix)) == 0)
            continue;
        if (w != i)
            strcpy_s(st->line[w], MAX_PATH, st->line[i]);
        w++;
    }
    st->n = w;
}

static void stateSave(const State *st, const char *appDir)
{
    char path[MAX_PATH];
    FILE *f;
    int i;
    snprintf(path, sizeof path, "%s\\exstar_mods.state", appDir);
    f = fopen(path, "wb");
    if (!f)
        return;
    fprintf(f, "; exstar-mods/1 - files installed by ExStarModManager\n");
    for (i = 0; i < st->n; i++)
        fprintf(f, "%s\n", st->line[i]);
    fclose(f);
}

/* ------------------------------------------------------------------ */
/* installer core                                                      */
/* ------------------------------------------------------------------ */

static char  g_appDir[MAX_PATH] = DEFAULT_APP_DIR;
static FILE *g_report;            /* CLI stdout sink, NULL in GUI mode */
static float  g_cliScale = -1.0f; /* CLI --scale, -1 = not given       */
static float  g_cliDim   = -1.0f; /* CLI --dim,   -1 = not given       */
static HWND   g_mainHwnd;         /* GUI window (journal target), 0 in CLI */

/* Both channels reach the GUI through the message queue. A job runs on a
 * worker thread, and a modal box from there would freeze the job - and
 * the progress animation with it - until the user finds the dialog, so
 * warnings are queued and shown once the interface is live again.      */
static void vreport(int journal, const wchar_t *fmt, va_list ap)
{
    wchar_t buf[1024];

    vswprintf(buf, 1024, fmt, ap);
    if (g_report) {
        char a[2048];
        w2a(buf, a, sizeof a);
        fputs(a, g_report);
        fflush(g_report);
    } else if (g_mainHwnd) {
        size_t cb = (wcslen(buf) + 1) * sizeof *buf;
        wchar_t *cp = (wchar_t *) HeapAlloc(GetProcessHeap(), 0, cb);

        if (cp) {
            memcpy(cp, buf, cb);
            if (!PostMessageW(g_mainHwnd, journal ? WM_APP + 2 : WM_APP + 3,
                              0, (LPARAM) cp))
                HeapFree(GetProcessHeap(), 0, cp);
        }
    } else {
        MessageBoxW(NULL, buf, L"ExStarModManager", MB_OK | MB_ICONWARNING);
    }
}

/* warning / needs attention -> dialog in GUI mode */
static void report(const wchar_t *fmt, ...)
{
    va_list ap;
    va_start(ap, fmt);
    vreport(0, fmt, ap);
    va_end(ap);
}

/* progress info -> journal in GUI mode */
static void note(const wchar_t *fmt, ...)
{
    va_list ap;
    va_start(ap, fmt);
    vreport(1, fmt, ap);
    va_end(ap);
}

/* Verify the app directory, reject foreign winmm.dll, (re)place core. */
static BOOL ensureCore(State *st)
{
    char exePath[MAX_PATH], winmm[MAX_PATH], real[MAX_PATH], sys[MAX_PATH];

    snprintf(exePath, sizeof exePath, "%s\\" APP_EXE_A, g_appDir);
    if (!pathExistsA(exePath)) {
        report(L"The selected folder has no %ls - choose the application folder.", APP_EXE_NAME);
        return FALSE;
    }

    snprintf(winmm, sizeof winmm, "%s\\winmm.dll", g_appDir);
    snprintf(real, sizeof real, "%s\\winmm_real.dll", g_appDir);

    if (pathExistsA(winmm)) {
        if (!fileOriginalEq(winmm, PROXY_MARKER)) {
            report(L"The app folder already has a foreign winmm.dll "
                   L"(not our proxy). Install aborted to avoid "
                   L"breaking anything.");
            return FALSE;
        }
    }
    if (pathExistsA(real) && fileOriginalEq(real, PROXY_MARKER)) {
        report(L"Odd: winmm_real.dll is marked as our proxy. "
               L"Delete the file manually and retry.");
        return FALSE;
    }

    /* system winmm must exist and be genuinely the system one */
    GetSystemDirectoryA(sys, sizeof sys);
    strcat_s(sys, sizeof sys, "\\winmm.dll");
    if (!pathExistsA(sys)) {
        report(L"System winmm.dll not found.");
        return FALSE;
    }

    if (!resourceWrite(L"BOOT_WINMM", winmm)) {
        reportWriteErr("winmm.dll", GetLastError());
        return FALSE;
    }
    stateAdd(st, "winmm.dll");

    {
        char host[MAX_PATH];
        snprintf(host, sizeof host, "%s\\ExStarRec.dll", g_appDir);
        if (!resourceWrite(L"HOST", host)) {
            reportWriteErr("ExStarRec.dll", GetLastError());
            return FALSE;
        }
        stateAdd(st, "ExStarRec.dll");
    }

    if (!CopyFileA(sys, real, FALSE)) {
        reportWriteErr("winmm_real.dll", GetLastError());
        return FALSE;
    }
    stateAdd(st, "winmm_real.dll");

    {
        char dir[MAX_PATH];
        snprintf(dir, sizeof dir, "%s\\modules", g_appDir);
        ensureDirA(dir);
    }
    return TRUE;
}

static void iniPathFor(char *out, size_t cap, const char *rel)
{
    snprintf(out, cap, "%s\\%s", g_appDir, rel);
}

/* ------------------------------------------------------------------ */
/* flat "key = value" file editing (modules\<id>.ini)                  */
/* keeps every other line (comments included); replaces the first      */
/* `key` line, appends when absent; creates the file when missing      */
/* ------------------------------------------------------------------ */

static BOOL iniSetKeyFile(const char *path, const char *key, const char *value)
{
    static char in[8192];
    char out[8192];
    HANDLE f;
    DWORD got = 0;
    size_t kl = strlen(key), wp2 = 0;
    BOOL replaced = FALSE;
    char *ln, *nx;

    f = CreateFileA(path, GENERIC_READ, FILE_SHARE_READ | FILE_SHARE_WRITE,
                    NULL, OPEN_EXISTING, FILE_ATTRIBUTE_NORMAL, NULL);
    if (f != INVALID_HANDLE_VALUE) {
        ReadFile(f, in, sizeof in - 1, &got, NULL);
        CloseHandle(f);
        in[got] = 0;
    } else if (GetLastError() == ERROR_FILE_NOT_FOUND) {
        in[0] = 0;
    } else {
        return FALSE;
    }

    for (ln = in; *ln; ln = nx) {
        char *s = ln, *eq, *k;
        size_t ll;

        nx = strchr(ln, '\n');
        if (nx)
            *nx++ = 0;
        ll = strlen(ln);                 /* drop CR of CRLF line endings */
        if (ll && ln[ll - 1] == '\r')
            ln[ll - 1] = 0;
        if (wp2 + 512 > sizeof out)
            return FALSE;
        while (*s == ' ' || *s == '\t')
            s++;
        eq = strchr(s, '=');
        if (!replaced && eq && (size_t)(eq - s) >= kl
            && _strnicmp(s, key, kl) == 0) {
            k = s + kl;
            while (*k == ' ' || *k == '\t')
                k++;
            if (*k == '=') {
                wp2 += (size_t)snprintf(out + wp2, sizeof out - wp2,
                                        "%s = %s\r\n", key, value);
                replaced = TRUE;
                continue;
            }
        }
        wp2 += (size_t)snprintf(out + wp2, sizeof out - wp2, "%s\r\n", ln);
    }
    if (!replaced)
        wp2 += (size_t)snprintf(out + wp2, sizeof out - wp2, "%s = %s\r\n",
                                key, value);

    f = CreateFileA(path, GENERIC_WRITE, 0, NULL, CREATE_ALWAYS,
                    FILE_ATTRIBUTE_NORMAL, NULL);
    if (f == INVALID_HANDLE_VALUE)
        return FALSE;
    WriteFile(f, out, (DWORD)wp2, &got, NULL);
    CloseHandle(f);
    return TRUE;
}

static float iniGetKeyF(const char *path, const char *key, float dflt)
{
    char in[4096];
    HANDLE f;
    DWORD got = 0;
    char *ln, *nx;
    size_t kl = strlen(key);

    f = CreateFileA(path, GENERIC_READ, FILE_SHARE_READ | FILE_SHARE_WRITE,
                    NULL, OPEN_EXISTING, FILE_ATTRIBUTE_NORMAL, NULL);
    if (f == INVALID_HANDLE_VALUE)
        return dflt;
    ReadFile(f, in, sizeof in - 1, &got, NULL);
    CloseHandle(f);
    in[got] = 0;

    for (ln = in; *ln; ln = nx) {
        char *s = ln, *eq, *k;

        nx = strchr(ln, '\n');
        if (nx)
            *nx++ = 0;
        while (*s == ' ' || *s == '\t')
            s++;
        eq = strchr(s, '=');
        if (!eq || _strnicmp(s, key, kl) != 0)
            continue;
        k = s + kl;
        while (*k == ' ' || *k == '\t')
            k++;
        if (*k != '=')
            continue;
        {
            float v;
            if (sscanf(k + 1, "%f", &v) == 1)
                return v;
        }
    }
    return dflt;
}

/* raw string value of `key` (trimmed) from a flat key = value file */
static BOOL iniGetKeyS(const char *path, const char *key, char *out, size_t cap)
{
    static char in[4096];
    HANDLE f;
    DWORD got = 0;
    char *ln, *nx;
    size_t kl = strlen(key);

    f = CreateFileA(path, GENERIC_READ, FILE_SHARE_READ | FILE_SHARE_WRITE,
                    NULL, OPEN_EXISTING, FILE_ATTRIBUTE_NORMAL, NULL);
    if (f == INVALID_HANDLE_VALUE)
        return FALSE;
    ReadFile(f, in, sizeof in - 1, &got, NULL);
    CloseHandle(f);
    in[got] = 0;

    for (ln = in; *ln; ln = nx) {
        char *s = ln, *eq, *k, *ve;
        size_t vl;

        nx = strchr(ln, '\n');
        if (nx)
            *nx++ = 0;
        while (*s == ' ' || *s == '\t')
            s++;
        eq = strchr(s, '=');
        if (!eq || _strnicmp(s, key, kl) != 0)
            continue;
        k = s + kl;
        while (*k == ' ' || *k == '\t')
            k++;
        if (*k != '=')
            continue;
        ve = k + 1;
        while (*ve == ' ' || *ve == '\t')
            ve++;
        vl = strlen(ve);
        while (vl && (ve[vl - 1] == ' ' || ve[vl - 1] == '\t'
                      || ve[vl - 1] == '\r'))
            vl--;
        if (vl >= cap)
            vl = cap - 1;
        memcpy(out, ve, vl);
        out[vl] = 0;
        return TRUE;
    }
    return FALSE;
}

/* ------------------------------------------------------------------ */
/* animator: one shared ~8ms timer interpolates every animated float    */
/* (toggles, hover, card intro, nav, page slide, smooth scroll). The    */
/* timer is armed on interaction and dies when everything settled.      */
/* ------------------------------------------------------------------ */
typedef struct {
    float    cur, from, to;
    ULONGLONG t0;                          /* start tick (delayed = past) */
    int      dur;                          /* ms; 0 = jump               */
    int      ease;                         /* EASE_OUT / EASE_BACK       */
} Anim;
#define EASE_OUT  0
#define EASE_BACK 1
#define ANIM_TIMER 77
#define ANIM_MS   8

static BOOL g_animOn;

static void animWake(void)
{
    if (!g_animOn && g_mainHwnd) {
        g_animOn = TRUE;
        SetTimer(g_mainHwnd, ANIM_TIMER, ANIM_MS, NULL);
    }
}
static float animEase(int kind, float t)
{
    if (kind == EASE_BACK) {                /* slight overshoot, springy */
        float c1 = 1.70158f, c3 = c1 + 1.0f, u = t - 1.0f;
        return 1.0f + c3 * u * u * u + c1 * u * u;
    }
    { float u = 1.0f - t; return 1.0f - u * u * u; }
}
static void animAt(Anim *a, float v)        /* jump without motion       */
{
    a->cur = a->from = a->to = v; a->t0 = 0; a->dur = 0; a->ease = EASE_OUT;
}
static void animTo(Anim *a, float to, int dur, int ease)
{
    if (a->dur == 0 && a->to == to)
        return;
    if (dur <= 0) { animAt(a, to); return; }
    a->from = a->cur; a->to = to; a->dur = dur; a->ease = ease;
    a->t0 = GetTickCount64();
    animWake();
}
static void animDelay(Anim *a, float from, float to, int dur, int ease,
                      int waitMs)
{
    a->cur = a->from = from; a->to = to; a->dur = dur; a->ease = ease;
    a->t0 = GetTickCount64() + (ULONGLONG) waitMs;
    animWake();
}
static BOOL animStep(Anim *a, ULONGLONG now) /* TRUE while still moving  */
{
    float t, e;
    if (a->dur <= 0) { a->cur = a->to; return FALSE; }
    if (now < a->t0)
        return TRUE;                         /* waiting out the delay    */
    t = (float) (now - a->t0) / (float) a->dur;
    if (t >= 1.0f) {
        BOOL was = a->cur != a->to;
        a->cur = a->to;
        a->dur = 0;
        return was;
    }
    e = animEase(a->ease, t);
    a->cur = a->from + (a->to - a->from) * e;
    return TRUE;
}
/* lerp two colors; t is clamped */
static COLORREF mix(COLORREF a, COLORREF b, float t)
{
    if (t < 0.0f) t = 0.0f;
    if (t > 1.0f) t = 1.0f;
    return RGB((int) (GetRValue(a) + (GetRValue(b) - GetRValue(a)) * t + 0.5f),
               (int) (GetGValue(a) + (GetGValue(b) - GetGValue(a)) * t + 0.5f),
               (int) (GetBValue(a) + (GetBValue(b) - GetBValue(a)) * t + 0.5f));
}

/* hover/press state for our custom controls:
 * [0..g_modCount) switches, [MAX_MODS] browse, [MAX_MODS+1] restore,
 * slider block (MAX_SLIDERS per module), preset pill block
 * (MAX_PRESETS per module) */
#define CKIND_SWITCH  0
#define CKIND_BUTTON  1
#define CKIND_DANGER  2
#define CKIND_SLIDER  3
#define CKIND_PRESET  4
#define CKIND_FILEBTN 5
#define CKIND_NAV     6
typedef struct {
    int                kind;
    int                idx;
    int                pi;                /* CKIND_PRESET: pill index   */
    BOOL               hover;
    BOOL               pressed;
    float              fval, fmin, fmax;  /* CKIND_SLIDER state */
    const SliderDef   *sdef;              /* CKIND_SLIDER config */
    const PresetDef   *pdef;              /* CKIND_PRESET config */
    HWND               hwnd;              /* self, for per-frame repaints */
    Anim               ha, pa;            /* animated hover / press      */
} ExCtrl;
#define CTL_SLIDER(m, s)  (&g_ctrls[MAX_MODS + 2 + (m) * MAX_SLIDERS + (s)])
#define CTL_PRESET(m, p)  (&g_ctrls[MAX_MODS + 2 + MAX_MODS * MAX_SLIDERS \
                              + (m) * MAX_PRESETS + (p)])
#define CTL_FILEBTN(m, b) (&g_ctrls[MAX_MODS + 2 + MAX_MODS * MAX_SLIDERS \
                              + MAX_MODS * MAX_PRESETS + (m) * MAX_FILEBTNS + (b)])
static ExCtrl g_ctrls[MAX_MODS * (MAX_SLIDERS + MAX_PRESETS + MAX_FILEBTNS + 1) + 2];

static int  g_presetSel[MAX_MODS]; /* selected pill, -1 = none (owner-drawn)   */

/* user wallpaper image placed next to the wallpaper module DLL; the
 * slot budget is the stock JPEG size in AppUi.dll, the wallpaper module
 * can only shrink into it (a fresh scan of the live DLL, 2026-11-14) */
#define WALLPAPER_FILE L"wallpaper.jpg"
#define WP_SLOT_BUDGET 837517

static void status(const wchar_t *fmt, ...);

/* write one key into modules\<id>.ini, creating the file from the
 * embedded template when it is missing;
 * out: 1 = stored, 0 = failed, -1 = nothing installed (no target dir) */
static int writeIniSetting(int idx, const char *key, const char *val)
{
    char iniRel[MAX_PATH], iniAbs[MAX_PATH];

    snprintf(iniRel, sizeof iniRel, "modules\\%s.ini", g_mods[idx].id);
    iniPathFor(iniAbs, sizeof iniAbs, iniRel);
    if (!pathExistsA(iniAbs) && !resourceWrite(g_mods[idx].resIni, iniAbs))
        return -1;
    return iniSetKeyFile(iniAbs, key, val) ? 1 : 0;
}

static int sliderDecimals(const SliderDef *d)
{
    if (d->isInt)
        return 0;
    return (d->step > 0.0f && d->step < 0.1f) ? 2 : 1;
}

/* human-readable value in display units: "20", "0.10 mm", "1.6\u00D7" */
static void sliderDisplayTextW(const SliderDef *d, float v, BOOL withUnit,
                               wchar_t *out, int cap)
{
    wchar_t num[16];
    int dec = sliderDecimals(d);

    if (dec == 0)
        swprintf(num, 16, L"%d", (int)(v + 0.5f));
    else
        swprintf(num, 16, L"%.*f", dec, (double)v);
    if (withUnit && d->unit && d->unit[0]) {
        if (lstrlenW(d->unit) > 1)            /* "0.10 mm" gets a space   */
            swprintf(out, cap, L"%ls %ls", num, d->unit);
        else                                  /* "1.6\u00D7" does not          */
            swprintf(out, cap, L"%ls%ls", num, d->unit);
    } else {
        wcsncpy(out, num, (size_t)cap - 1);
        out[cap - 1] = 0;
    }
}

/* the string stored in the ini (iniMul converts mm display -> \u00B5m storage) */
static void sliderValueText(const SliderDef *d, float v, char *out, size_t cap)
{
    float w = d->iniMul ? v * d->iniMul : v;

    if (d->isInt || d->iniMul)
        snprintf(out, cap, "%d", (int)(w + 0.5f));
    else
        snprintf(out, cap, "%.1f", (double)w);
}

static void applySliderSetting(int idx, int s)
{
    const SliderDef *d = &g_mods[idx].sliders[s];
    ExCtrl *c = CTL_SLIDER(idx, s);
    wchar_t disp[40];
    char val[24];
    int rc;

    sliderValueText(d, c->fval, val, sizeof val);
    rc = writeIniSetting(idx, d->key, val);
    sliderDisplayTextW(d, c->fval, TRUE, disp, 40);
    if (rc < 0)
        status(L"%ls: %ls = %ls - will be stored on install.",
               g_mods[idx].title, d->label, disp);
    else if (rc > 0)
        status(L"%ls: %ls = %ls - applies after restarting "
               L"EXStar Hub.", g_mods[idx].title, d->label, disp);
    else
        status(L"%ls: failed to save %ls.",
               g_mods[idx].title, d->label);
}

/* --- quality preset pills ----------------------------------------------
 * The three green thresholds are coupled, so one pill writes all of
 * them into the marker_quality ini keys at once. */

/* the pill whose spread is closest to the current ini value;
 * a missing key reads as the module default (100 um = "Medium") */
static int nearestPreset(int idx, const char *iniAbs)
{
    const PresetDef *pr = g_mods[idx].presets;
    int n = g_mods[idx].nPresets, best, i;
    float spread;

    if (n <= 0)
        return -1;
    spread = iniGetKeyF(iniAbs, "green_spread_um", 100.0f);
    best = 0;
    for (i = 1; i < n; i++) {
        float da = spread - (float) pr[i].spreadUm;
        float db = spread - (float) pr[best].spreadUm;

        if (da < 0) da = -da;
        if (db < 0) db = -db;
        if (da < db)
            best = i;
    }
    return best;
}

/* the pill row is owner-drawn on the page: a page repaint refreshes it */
static void invalidatePages(void);       /* defined with the page painters */
static void presetSelRefresh(void)
{
    invalidatePages();
}

static void applyPreset(int idx, int p)
{
    const PresetDef *pr = &g_mods[idx].presets[p];
    char val[24];
    int r1, r2, r3;

    snprintf(val, sizeof val, "%d", pr->spreadUm);
    r1 = writeIniSetting(idx, "green_spread_um", val);
    snprintf(val, sizeof val, "%d", pr->frames);
    r2 = writeIniSetting(idx, "green_frames", val);
    snprintf(val, sizeof val, "%d", pr->supported);
    r3 = writeIniSetting(idx, "green_supported", val);

    if (r1 == 0 || r2 == 0 || r3 == 0) {
        status(L"%ls: failed to save preset \"%ls\".",
               g_mods[idx].title, pr->label);
        return;
    }
    g_presetSel[idx] = p;
    presetSelRefresh();
    if (r1 < 0 || r2 < 0 || r3 < 0)
        status(L"%ls: preset \"%ls\" (%ls, %d frames, %d views) - "
               L"will be stored on install.",
               g_mods[idx].title, pr->label, pr->spreadText,
               pr->frames, pr->supported);
    else
        status(L"%ls: preset \"%ls\" (%ls, %d frames, %d views) - "
               L"applies after restarting EXStar Hub.",
               g_mods[idx].title, pr->label, pr->spreadText,
               pr->frames, pr->supported);
}

/* Sibling processes (scanservice.exe, Sn3DprocessManager.exe, ...) only
 * ever carry module code for modules explicitly PROVEN there.
 * Evidence 2026-11-24: six modules inside scanservice.exe aborted it
 * (0xc0000409 in ucrtbase -> vendor error 0x00000012 on project open),
 * while selective_mesh alone (then named merge_select) ran a full night
 * there.  A writer that trusted the per-module needsSiblings flag
 * re-armed the six-module configuration at 18:42 (manager 1.6.3) and the
 * 0x00000012 came back.  selective_mesh *is* needed in scanservice.exe -
 * that process builds the post-mesh data the Mesh Model window shows -
 * so the supported configuration is the manual pair
 *   sibling_all = 1
 *   sibling_modules = selective_mesh
 * and this code never rewrites existing sibling keys: only a fresh
 * modules.ini (no keys yet) gets the safe default.  The one exception is
 * migrateRenamedIds(), which renames tokens, never adds or removes one. */

/* 1.6.0 renamed merge_select to selective_mesh. A hand-tuned
 * [host] sibling_modules list names the OLD id, and defaultSiblingKeys
 * below never rewrites existing keys, so without this the renamed
 * module would silently lose its sibling slot - the merge gate then
 * never runs in scanservice.exe, which is exactly where the post-mesh
 * data is built. Only whole tokens are replaced; the list's order,
 * spacing style and every other module in it stay as written. */
static void migrateRenamedIds(IniDoc *ini)
{
    Sec *hs = iniSec(ini, "host");
    int i;

    if (!hs)
        return;
    for (i = 0; i < hs->n; i++) {
        char out[128], tok[64];
        const char *p;
        BOOL changed = FALSE;

        if (_stricmp(hs->kv[i].key, "sibling_modules") != 0
            || !strstr(hs->kv[i].val, "merge_select"))
            continue;
        out[0] = 0;
        p = hs->kv[i].val;
        while (*p) {
            const char *c = strchr(p, ',');
            size_t len = c ? (size_t)(c - p) : strlen(p);

            while (len && (*p == ' ' || *p == '\t')) { p++; len--; }
            while (len && (p[len - 1] == ' ' || p[len - 1] == '\t'))
                len--;
            if (len) {
                if (len >= sizeof tok)
                    len = sizeof tok - 1;
                memcpy(tok, p, len);
                tok[len] = 0;
                if (_stricmp(tok, "merge_select") == 0) {
                    strcpy_s(tok, sizeof tok, "selective_mesh");
                    changed = TRUE;
                }
                if (out[0])
                    strncat_s(out, sizeof out, ",", _TRUNCATE);
                strncat_s(out, sizeof out, tok, _TRUNCATE);
            }
            if (!c)
                break;
            p = c + 1;
        }
        if (changed) {
            iniSet(hs, "sibling_modules", out);
            note(L"Sibling list updated: merge_select -> selective_mesh.");
        }
        break;
    }
}

static void defaultSiblingKeys(IniDoc *ini)
{
    Sec *hs = iniSec(ini, "host");
    int i;

    if (!hs)
        return;
    for (i = 0; i < hs->n; i++)
        if (_stricmp(hs->kv[i].key, "sibling_all") == 0
            || _stricmp(hs->kv[i].key, "sibling_modules") == 0)
            return;
    iniSet(hs, "sibling_all", "0");
    iniSet(hs, "sibling_modules", "");
}

/* install modules from the bitmask; others -> enabled=0 */
static BOOL doInstall(UINT mask)
{
    State st;
    IniDoc ini;
    char iniPath[MAX_PATH];
    int i;
    BOOL any = FALSE;

    if (mask == 0) {
        report(L"No module selected.");
        return FALSE;
    }
    if (appRunning()) {
        note(L"Application is running - closing it to install.");
        killApp();
    }
    stateLoad(&st, g_appDir);
    if (!ensureCore(&st)) {
        return FALSE;
    }

    iniPathFor(iniPath, sizeof iniPath, "modules.ini");
    if (!iniLoad(&ini, iniPath)) {
        memset(&ini, 0, sizeof ini);
    }
    {   /* discoverable default, but never overwrite a user's choice */
        Sec *hs = iniSec(&ini, "host");
        int j, hasLog = 0;
        for (j = 0; hs && j < hs->n; j++)
            if (_stricmp(hs->kv[j].key, "log") == 0)
                hasLog = 1;
        if (hs && !hasLog)
            iniSet(hs, "log", "0");
    }

    for (i = 0; i < g_modCount; i++) {
        const ModDef *m = &g_mods[i];
        char dllRel[MAX_PATH], iniRel[MAX_PATH];
        char dllAbs[MAX_PATH], iniAbs[MAX_PATH];

        snprintf(dllRel, sizeof dllRel, "modules\\%s.dll", m->id);
        snprintf(iniRel, sizeof iniRel, "modules\\%s.ini", m->id);
        iniPathFor(dllAbs, sizeof dllAbs, dllRel);
        iniPathFor(iniAbs, sizeof iniAbs, iniRel);

        if (mask & (1u << i)) {
            if (!resourceWrite(m->resDll, dllAbs)) {
                reportWriteErr(dllRel, GetLastError());
                return FALSE;
            }
            if (!pathExistsA(iniAbs) && !resourceWrite(m->resIni, iniAbs)) {
                reportWriteErr(iniRel, GetLastError());
                return FALSE;
            }
            stateAdd(&st, dllRel);
            stateAdd(&st, iniRel);
            iniSet(iniSec(&ini, m->id), "enabled", "1");
            {   /* persist the adjustable knobs: the GUI stores what its
                 * sliders show; the CLI knows "scale" (--scale) and
                 * "dim_alpha" (--dim), other keys keep the ini value */
                int s;
                for (s = 0; s < m->nSliders; s++) {
                    const SliderDef *d = &m->sliders[s];
                    float v;
                    char val[24];

                    if (g_report) {
                        if (strcmp(d->key, "scale") == 0 && g_cliScale >= 1.0f)
                            v = g_cliScale;
                        else if (strcmp(d->key, "dim_alpha") == 0 && g_cliDim >= 0.0f)
                            v = g_cliDim;
                        else
                            continue;    /* CLI knob not given: keep ini  */
                    } else {
                        v = CTL_SLIDER(i, s)->fval;
                    }
                    sliderValueText(d, v, val, sizeof val);
                    iniSetKeyFile(iniAbs, d->key, val);
                }
                if (!g_report && m->nPresets && g_presetSel[i] >= 0) {
                    const PresetDef *pr = &m->presets[g_presetSel[i]];
                    char val[24];   /* GUI: store the whole pill bundle  */

                    snprintf(val, sizeof val, "%d", pr->spreadUm);
                    iniSetKeyFile(iniAbs, "green_spread_um", val);
                    snprintf(val, sizeof val, "%d", pr->frames);
                    iniSetKeyFile(iniAbs, "green_frames", val);
                    snprintf(val, sizeof val, "%d", pr->supported);
                    iniSetKeyFile(iniAbs, "green_supported", val);
                }
            }
            note(L"Module installed and enabled: %ls %hs. "
                   L"Restart EXStar Hub.", m->title, m->version);
            any = TRUE;
        }
    }

    for (i = 0; g_legacy[i]; i++) {
        char rel[MAX_PATH], abs[MAX_PATH];
        BOOL had = FALSE;

        snprintf(rel, sizeof rel, "modules\\%s.dll", g_legacy[i]);
        iniPathFor(abs, sizeof abs, rel);
        if (pathExistsA(abs) && DeleteFileA(abs))
            had = TRUE;
        stateDrop(&st, rel);

        snprintf(rel, sizeof rel, "modules\\%s.ini", g_legacy[i]);
        iniPathFor(abs, sizeof abs, rel);
        DeleteFileA(abs);
        stateDrop(&st, rel);

        iniRemoveSec(&ini, g_legacy[i]);
        if (had)
            note(L"Removed legacy module: %hs.", g_legacy[i]);
    }

    {   /* 1.6.0 rename: carry the module's own switch file along before
         * the loop below writes a fresh one (it only writes when the
         * target is missing) and before the legacy cleanup deletes the
         * old file.  Same copy on remove would be wrong - there the user
         * asked for the module to go. */
        char oldRel[MAX_PATH], oldAbs[MAX_PATH], newRel[MAX_PATH], newAbs[MAX_PATH];

        snprintf(oldRel, sizeof oldRel, "modules\\%s.ini", "merge_select");
        snprintf(newRel, sizeof newRel, "modules\\%s.ini", "selective_mesh");
        iniPathFor(oldAbs, sizeof oldAbs, oldRel);
        iniPathFor(newAbs, sizeof newAbs, newRel);
        if (pathExistsA(oldAbs) && !pathExistsA(newAbs)
            && CopyFileA(oldAbs, newAbs, TRUE)) {
            stateAdd(&st, newRel);
            note(L"Settings carried over: merge_select.ini -> "
                 L"selective_mesh.ini.");
        }
    }

    migrateRenamedIds(&ini);
    defaultSiblingKeys(&ini);
    iniSave(&ini, iniPath);
    stateAdd(&st, "modules.ini");
    stateSave(&st, g_appDir);

    if (any)
        note(L"Done. Restart EXStar Hub.");
    return any;
}

static BOOL doRemove(UINT mask)
{
    State st;
    IniDoc ini;
    char iniPath[MAX_PATH];
    int i;

    if (mask == 0) {
        report(L"No module selected.");
        return FALSE;
    }
    if (appRunning()) {
        note(L"Application is running - closing it.");
        killApp();
    }
    stateLoad(&st, g_appDir);
    iniPathFor(iniPath, sizeof iniPath, "modules.ini");
    iniLoad(&ini, iniPath);

    for (i = 0; i < g_modCount; i++) {
        const ModDef *m = &g_mods[i];
        char rel[MAX_PATH], abs[MAX_PATH];

        if (!(mask & (1u << i)))
            continue;
        snprintf(rel, sizeof rel, "modules\\%s.dll", m->id);
        iniPathFor(abs, sizeof abs, rel);
        DeleteFileA(abs);
        stateDrop(&st, rel);

        /* modules\<id>.ini is deliberately KEPT: it holds the user's
         * settings, so re-enabling the module restores its config.
         * "restore stock" removes everything. */
        iniRemoveSec(&ini, m->id);
        note(L"Module %ls disabled and removed (settings file kept). "
               L"Restart EXStar Hub.", m->title);
    }
    defaultSiblingKeys(&ini);
    iniSave(&ini, iniPath);
    stateSave(&st, g_appDir);
    return TRUE;
}

static BOOL doRestore(void)
{
    State st;
    char statePath[MAX_PATH];
    int i;
    BOOL had = stateLoad(&st, g_appDir);

    if (appRunning()) {
        note(L"Application is running - closing it.");
        killApp();
    }

    if (!had || st.n == 0) {
        /* no manifest - fall back to the canonical list */
        strcpy_s(st.line[st.n++], MAX_PATH, "winmm.dll");
        strcpy_s(st.line[st.n++], MAX_PATH, "winmm_real.dll");
        strcpy_s(st.line[st.n++], MAX_PATH, "ExStarRec.dll");
        strcpy_s(st.line[st.n++], MAX_PATH, "modules.ini");
        for (i = 0; i < g_modCount; i++) {
            char rel[MAX_PATH];
            snprintf(rel, sizeof rel, "modules\\%s.dll", g_mods[i].id);
            strcpy_s(st.line[st.n++], MAX_PATH, rel);
            snprintf(rel, sizeof rel, "modules\\%s.ini", g_mods[i].id);
            strcpy_s(st.line[st.n++], MAX_PATH, rel);
        }
        strcpy_s(st.line[st.n++], MAX_PATH, "modules\\wallpaper.jpg");
        for (i = 0; g_legacy[i]; i++) {
            char rel[MAX_PATH];
            snprintf(rel, sizeof rel, "modules\\%s.dll", g_legacy[i]);
            strcpy_s(st.line[st.n++], MAX_PATH, rel);
            snprintf(rel, sizeof rel, "modules\\%s.ini", g_legacy[i]);
            strcpy_s(st.line[st.n++], MAX_PATH, rel);
        }
    }

    for (i = 0; i < st.n; i++) {
        char abs[MAX_PATH];
        iniPathFor(abs, sizeof abs, st.line[i]);
        if (DeleteFileA(abs))
            note(L"Deleted file: %hs", st.line[i]);
        else if (pathExistsA(abs))
            report(L"FAILED to delete %hs (err=%lu)", st.line[i], GetLastError());
    }
    {
        char dir[MAX_PATH];
        snprintf(dir, sizeof dir, "%s\\modules", g_appDir);
        if (RemoveDirectoryA(dir))
            note(L"Deleted folder modules\\");
    }
    snprintf(statePath, sizeof statePath, "%s\\exstar_mods.state", g_appDir);
    DeleteFileA(statePath);
    note(L"Application restored to stock.");
    return TRUE;
}

