/* ------------------------------------------------------------------ */
/* UI scaling: every pixel constant in the GUI goes through U().     */
/* g_us = max(system DPI / 96, physical ppi / 96); 4K panels that    */
/* Windows still runs at 96 dpi are detected by their real size.     */
/* ExStarModManager.exe --zoom 1.5 forces the factor (1.0 .. 4.0).   */
/* ------------------------------------------------------------------ */
static float g_us = 1.0f;
static float g_usForce = 0.0f;
#define U(x) ((int)((x) * g_us + 0.5f))

static void uiScaleInit(void)
{
    HDC dc = GetDC(NULL);
    float best = 1.0f;

    if (dc) {
        int dpi = GetDeviceCaps(dc, LOGPIXELSX);
        int mmW = GetDeviceCaps(dc, PHYSICALWIDTH);
        int pxW = GetDeviceCaps(dc, HORZRES);

        ReleaseDC(NULL, dc);
        if (dpi >= 96 && (float)dpi / 96.0f > best)
            best = (float)dpi / 96.0f;
        /* physical density, when the driver reports a sane panel size */
        if (mmW >= 100 && mmW <= 3000 && pxW > 0) {
            float ppi = (float)pxW / ((float)mmW / 25.4f);
            if (ppi > 60.0f && ppi < 400.0f && ppi / 96.0f > best)
                best = ppi / 96.0f;
        }
    }
    if (g_usForce > 0.0f)
        best = g_usForce;
    g_us = best > 2.5f ? 2.5f : best;
}

